#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int cmpstr(const void *a, const void *b) {
    return strcmp((const char *)a, (const char *)b);
}

int lookup(const char *key, char arr[][11], int m) {
    int lo = 0, hi = m - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        int c = strcmp(key, arr[mid]);
        if (c == 0) return mid;
        if (c < 0) hi = mid - 1;
        else lo = mid + 1;
    }
    return -1;
}

int main() {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    char (*all)[11] = malloc(sizeof(char[11]) * N);
    for (int i = 0; i < N; i++) {
        scanf("%s", all[i]);
    }

    qsort(all, N, sizeof(all[0]), cmpstr);

    char (*uniq)[11] = malloc(sizeof(char[11]) * N);
    int *freq = malloc(sizeof(int) * N);
    int m = 0;

    for (int i = 0; i < N; ) {
        strcpy(uniq[m], all[i]);
        freq[m] = 0;
        while (i < N && strcmp(all[i], uniq[m]) == 0) {
            freq[m]++;
            i++;
        }
        m++;
    }

    long long ans = 0;
    char subs[55][11];

    for (int u = 0; u < m; u++) {
        int len = strlen(uniq[u]);
        int k = 0;

        for (int i = 0; i < len; i++) {
            for (int j = i; j < len; j++) {
                int L = j - i + 1;
                memcpy(subs[k], uniq[u] + i, L);
                subs[k][L] = '\0';
                k++;
            }
        }

        qsort(subs, k, sizeof(subs[0]), cmpstr);

        long long F = 0;
        for (int i = 0; i < k; i++) {
            if (i == 0 || strcmp(subs[i], subs[i - 1]) != 0) {
                int idx = lookup(subs[i], uniq, m);
                if (idx != -1) {
                    F += freq[idx];
                }
            }
        }

        ans += (long long)freq[u] * (F - 1);
    }

    printf("%lld\n", ans);

    free(all);
    free(uniq);
    free(freq);

    return 0;
}
